export const meta = {
  name: 'spec-coverage-audit',
  description: 'Map every clause of telelean spec v4.1 to where it is built or planned (slice 1 code, slice 2 and 3 plans) or unassigned; adversarially check the gaps; write a coverage report',
  phases: [{ title: 'Map' }, { title: 'Check gaps' }, { title: 'Report' }],
}
const R = '/home/zhengyew/telelean'
const S = '/tmp/claude-1000/-home-zhengyew-telelean/20626c17-0334-4498-ad86-9dc24b7010ed/scratchpad'
const SPEC = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/01_spec_v4.md'
const AP = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/02_autopilot_decisions.md'
const P1 = R + '/docs/slice1-plan.md'
const P2 = R + '/docs/slice2-plan.md'
const P3 = S + '/plans/slice3-plan.md'
const OUT = S + '/plans/coverage_audit.md'
const SAFETY = `SAFETY AND RESOURCE RULES (mandatory): READ-ONLY everywhere (the one exception, for the report writer only, is the file ${OUT}). Never change git state (read-only git is fine). No network, no installs, no Claude CLI, no builds, no tests, no Lean, no tsc/vitest: other agents are building slice 2 in the same working tree and editing the slice-3 plan right now, so files are in flux. Never touch ${R}/packages/extension/dist or out. Never send, post, upload or publish anything.`
const CONTEXT = `Context: telelean (${R}) is a VS Code extension (packages/core, runner, extension, webview) that shows a user's beliefs as cards backed by Lean 4 files; Claude formalises and proves; a non-LLM gate decides what counts. The user's spec is v4.1 (${SPEC}); it is being built on autopilot in five slices (spec Part 2, ★D8 (a)): 1 the new board (DONE: ${P1}, especially its §8 change log, and the code), 2 the review list (plan ${P2}, final; being built now: its §8 change log says what is built so far), 3 FROZEN (plan ${P3}, under review), 4 the transform window (not yet planned), 5 references (not yet planned). Every autopilot decision that departs from or narrows the spec is in ${AP} (AP-n) or in the plans' decision sections (D2-n, D3-n).`
const ROW = { type: 'object', properties: { clause: { type: 'string', description: 'clause id and sub-item, e.g. "FZ-9 bullet 3" or "A17"' }, requirement: { type: 'string', description: 'the requirement in one sentence' }, status: { type: 'string', enum: ['built', 'planned-slice2', 'planned-slice3', 'for-slice4', 'for-slice5', 'narrowed-by-decision', 'unassigned', 'contradicted'] }, where: { type: 'string', description: 'file:line or plan section(s) that implement/plan it, or the decision id that narrows it' }, note: { type: 'string' } }, required: ['clause', 'requirement', 'status', 'where'] }
const MAP = { type: 'object', properties: { summary: { type: 'string' }, rows: { type: 'array', items: ROW } }, required: ['summary', 'rows'] }
const PARTS = [
  { key: 'board', text: 'Spec Part 1 §1 Terms, §2 Cards and fields (CF-*), §3 The board (BD-*), §4 Arrows and dependencies (AR-*), and the parts of Appendix A (edge cases) about cards, the board and arrows.' },
  { key: 'frozen-menu-undo', text: 'Spec Part 1 §5 FROZEN (FZ-1..FZ-13, every bullet), §6 Selection and the CONTEXT MENU (CM-*), §12 UNDO AND REDO (UN-*), and the parts of Appendix A about freezing, selection and undo.' },
  { key: 'sessions-review', text: 'Spec Part 1 §7 EDIT SESSIONS (ES-*), §9 REVIEW STAGE (RV-*), §10 DECLINE OPTIONS (DO-*), §11 Ending a session (EN-*), and the parts of Appendix A about sessions, review and ending.' },
  { key: 'transform-refs-guarantees', text: 'Spec Part 1 §8 TRANSFORM (TR-*), §13 REFERENCE SYSTEM (RF-*), §14 What telelean guarantees mechanically (every numbered guarantee), Appendix B (B.1..B.7 and the backstop), the Part 3 safety issues S1..S22 and their resolutions, and the parts of Appendix A not about the board, freezing, sessions or review.' },
]
phase('Map')
const maps = await parallel(PARTS.map((p) => () => agent(`${SAFETY}\n\n${CONTEXT}\n\nYOUR PART OF THE SPEC: ${p.text}\n\nFor every clause in your part — and every bullet or sub-requirement inside a clause that states a distinct obligation — find where it is built (slice 1: code file:line, or ${P1} §8), planned (${P2} or ${P3}: section numbers), explicitly left to slice 4 or 5 by a plan, narrowed or changed by a logged decision (AP-n, D2-n, D3-n: give the id), contradicted by a plan or the code (say how), or UNASSIGNED (no slice built or plans it, and no decision drops it). Be exhaustive and precise: a requirement counts as planned only if a plan section actually commits to it (not just mentions the clause id). One row per distinct requirement.`, { label: `map:${p.key}`, phase: 'Map', schema: MAP })))
const rows = maps.filter(Boolean).flatMap((m) => m.rows)
const gaps = rows.filter((r) => r.status === 'unassigned' || r.status === 'contradicted')
log(`mapped ${rows.length} requirements; ${gaps.length} unassigned or contradicted`)
phase('Check gaps')
const VERD = { type: 'object', properties: { verdicts: { type: 'array', items: { type: 'object', properties: { clause: { type: 'string' }, real_gap: { type: 'boolean' }, where_if_covered: { type: 'string' }, recommended_slice: { type: 'string', description: '2, 3, 4, 5, or "decision" (narrow it with a logged decision)' }, reason: { type: 'string' } }, required: ['clause', 'real_gap', 'recommended_slice', 'reason'] } } }, required: ['verdicts'] }
const checked = gaps.length === 0 ? { verdicts: [] } : await agent(`${SAFETY}\n\n${CONTEXT}\n\nMappers flagged the requirements below as UNASSIGNED or CONTRADICTED. For each, try hard to show it IS covered (search all three plans, the slice-1 code, the decision logs) — or confirm the gap. For a real gap, recommend where it belongs: slice 2 (if it is review-list behaviour and must be in the plan now), 3 (FROZEN), 4 (transform), 5 (references), or "decision" (it should be narrowed or dropped by a logged autopilot decision, with the reason).\n\n=== FLAGGED ===\n${JSON.stringify(gaps, null, 1)}`, { label: 'check:gaps', phase: 'Check gaps', schema: VERD })
phase('Report')
const report = await agent(`${SAFETY} EXCEPTION: you write exactly ONE new file, ${OUT}.\n\n${CONTEXT}\n\nWrite the coverage report ${OUT} for the spec, from the mapping rows and the gap verdicts below. Structure: (1) summary counts per status and per spec section; (2) REAL GAPS first — a table with clause, requirement, recommended slice and why (these drive the next planning steps); (3) contradictions; (4) requirements narrowed by decisions (with the decision ids), so the user can review them in one place; (5) the full matrix, grouped by spec section, compact (one line per requirement). Also list what slice 4 (transform window) and slice 5 (references) must cover: every for-slice4/for-slice5 row plus the real gaps recommended there. Return a short summary: counts, the real gaps (one line each), and the slice-4/5 scope in a few lines.\n\n=== ROWS ===\n${JSON.stringify(rows, null, 1)}\n\n=== GAP VERDICTS ===\n${JSON.stringify(checked ? checked.verdicts : null, null, 1)}`, { label: 'report', phase: 'Report' })
return { rows: rows.length, gaps: gaps.length, checked, report }
